<?php
require_once __DIR__ . '/includes/bootstrap.php';
riderRequireLogin();
ensureMisTables();
$conn = dbConnect();
$riderId = (int) $_SESSION['rider_id'];

function riderDashboardRows($conn, $sql, $riderId) {
    $stmt = mysqli_prepare($conn, $sql);
    if (!$stmt) return array();
    mysqli_stmt_bind_param($stmt, 'i', $riderId);
    mysqli_stmt_execute($stmt);
    return mysqli_fetch_all(mysqli_stmt_get_result($stmt), MYSQLI_ASSOC);
}

$active = riderDashboardRows($conn, "SELECT a.assignment_id,a.orderid,a.status,a.assigned_at,o.name customer_name,o.address,f.total_amount FROM order_delivery_assignments a JOIN orders o ON o.orderid=a.orderid LEFT JOIN order_financials f ON f.orderid=o.orderid WHERE a.rider_id=? AND a.is_current=1 AND a.status NOT IN ('delivered','failed','reassigned') ORDER BY FIELD(a.status,'out_for_delivery','picked_up','accepted','assigned'),a.assigned_at", $riderId);
$history = riderDashboardRows($conn, "SELECT a.orderid,a.assigned_at,a.accepted_at,a.delivered_at,o.name customer_name,o.address,p.payment_method,f.total_amount,c.status collection_status FROM order_delivery_assignments a JOIN orders o ON o.orderid=a.orderid LEFT JOIN order_payments p ON p.orderid=o.orderid LEFT JOIN order_financials f ON f.orderid=o.orderid LEFT JOIN cod_collections c ON c.orderid=a.orderid WHERE a.rider_id=? AND a.status='delivered' ORDER BY a.delivered_at DESC LIMIT 12", $riderId);
$statsRows = riderDashboardRows($conn, "SELECT COUNT(*) completed, SUM(CASE WHEN DATE(delivered_at)=CURDATE() THEN 1 ELSE 0 END) today_completed, COALESCE(SUM(total_amount),0) delivered_value, AVG(CASE WHEN accepted_at IS NOT NULL AND delivered_at IS NOT NULL THEN TIMESTAMPDIFF(MINUTE,accepted_at,delivered_at) END) average_minutes FROM order_delivery_assignments a LEFT JOIN order_financials f ON f.orderid=a.orderid WHERE a.rider_id=? AND a.status='delivered'", $riderId);
$stats = $statsRows[0] ?? array('completed'=>0,'today_completed'=>0,'delivered_value'=>0,'average_minutes'=>null);
?><!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#ff4b1f"><title>Rider dashboard | Foodera</title><link rel="icon" type="image/png" href="../assets/branding/foodera-icon.png"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css"><link rel="stylesheet" href="css/rider.css"><link rel="stylesheet" href="css/dashboard.css"></head>
<body><main class="rider-shell rider-dashboard"><header class="rider-top"><div><div class="rider-brand"><img src="../assets/branding/foodera-wordmark.png" alt="Foodera"></div><p class="rider-kicker">Foodera delivery</p><h1>Hi, <?php echo riderEscape($_SESSION['rider_name']); ?></h1></div><div class="rider-top-actions"><a class="rider-history-link" href="home.php"><i class="bi bi-bicycle"></i> Manage deliveries</a><a href="logout.php">Sign out <i class="bi bi-box-arrow-right"></i></a></div></header>
<section class="rider-performance-intro"><div><p class="rider-kicker">Performance</p><h2>Your delivery overview</h2><p>Private operational history for your completed Foodera deliveries.</p></div><strong><i class="bi bi-bag-check"></i> <?php echo count($active); ?> active</strong></section>
<section class="rider-stat-grid" aria-label="Delivery performance"><article><i class="bi bi-check2-circle"></i><span>Completed deliveries</span><strong><?php echo (int) $stats['completed']; ?></strong></article><article><i class="bi bi-calendar-day"></i><span>Completed today</span><strong><?php echo (int) $stats['today_completed']; ?></strong></article><article><i class="bi bi-clock-history"></i><span>Average delivery time</span><strong><?php echo $stats['average_minutes'] === null ? '—' : (int) round($stats['average_minutes']) . ' min'; ?></strong></article><article><i class="bi bi-receipt"></i><span>Delivered order value</span><strong>Rs <?php echo number_format((float) $stats['delivered_value']); ?></strong></article></section>
<section class="rider-card rider-dashboard-section"><div class="rider-section-heading"><div><h2>Active deliveries</h2><p>Continue delivery tasks from the secure delivery workspace.</p></div><a class="rider-history-link" href="home.php">Open workspace <i class="bi bi-arrow-right"></i></a></div><?php if (!$active) { ?><p class="rider-empty-copy">No active deliveries right now. New tasks appear after dispatch assigns them to you.</p><?php } else { ?><div class="rider-active-list"><?php foreach ($active as $delivery) { ?><a href="home.php" class="rider-active-row"><span class="rider-status"><?php echo riderEscape(ucwords(str_replace('_', ' ', $delivery['status']))); ?></span><strong>Order #<?php echo (int) $delivery['orderid']; ?></strong><span><?php echo riderEscape($delivery['customer_name']); ?></span><small><?php echo riderEscape($delivery['address']); ?></small><b>Rs <?php echo number_format((float) $delivery['total_amount']); ?> <i class="bi bi-arrow-right"></i></b></a><?php } ?></div><?php } ?></section>
<section class="rider-card rider-dashboard-section"><div class="rider-section-heading"><div><h2>Completed delivery history</h2><p>Latest completed orders assigned to you. Customer phone numbers and OTPs are intentionally not shown here.</p></div><span class="rider-history-count"><?php echo count($history); ?> latest</span></div><?php if (!$history) { ?><p class="rider-empty-copy">Your completed delivery history will appear here after you verify a delivery.</p><?php } else { ?><div class="rider-history-wrap"><table class="rider-history-table"><thead><tr><th>Order</th><th>Customer / area</th><th>Payment</th><th>Value</th><th>Delivered</th></tr></thead><tbody><?php foreach ($history as $delivery) { ?><tr><td><strong>#<?php echo (int) $delivery['orderid']; ?></strong><small>Assigned <?php echo date('d M, h:i A', strtotime($delivery['assigned_at'])); ?></small></td><td><strong><?php echo riderEscape($delivery['customer_name']); ?></strong><small><?php echo riderEscape($delivery['address']); ?></small></td><td><?php echo riderEscape(strtoupper($delivery['payment_method'] ?? '')); ?><?php if (($delivery['payment_method'] ?? '') === 'cod') { ?><small class="rider-collection <?php echo riderEscape($delivery['collection_status'] ?? 'pending'); ?>">COD <?php echo riderEscape(ucwords(str_replace('_', ' ', $delivery['collection_status'] ?? 'pending'))); ?></small><?php } ?></td><td><strong>Rs <?php echo number_format((float) $delivery['total_amount']); ?></strong></td><td><strong><?php echo date('d M Y', strtotime($delivery['delivered_at'])); ?></strong><small><?php echo date('h:i A', strtotime($delivery['delivered_at'])); ?></small></td></tr><?php } ?></tbody></table></div><?php } ?></section></main></body></html>
